export type FarmsPluginRequirements = ClientWithRpc<GetAccountInfoApi & GetMultipleAccountsApi> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function farmsProgram() {
  return <T extends FarmsPluginRequirements>(
    client: T
  ): ExtendedClient<T, { farms: FarmsPlugin }> => {
    return extendClient(client, {
      farms: <FarmsPlugin>{
        accounts: {
          farmState: addSelfFetchFunctions(client, getFarmStateCodec()),
          globalConfig: addSelfFetchFunctions(client, getGlobalConfigCodec()),
          userState: addSelfFetchFunctions(client, getUserStateCodec()),
          oraclePrices: addSelfFetchFunctions(client, getOraclePricesCodec()),
        },
        instructions: {
          initializeGlobalConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getInitializeGlobalConfigInstruction(input)),
          updateGlobalConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateGlobalConfigInstruction(input)),
          initializeFarm: (input) =>
            addSelfPlanAndSendFunctions(client, getInitializeFarmInstruction(input)),
          initializeFarmDelegated: (input) =>
            addSelfPlanAndSendFunctions(client, getInitializeFarmDelegatedInstruction(input)),
          initializeReward: (input) =>
            addSelfPlanAndSendFunctions(client, getInitializeRewardInstruction(input)),
          addRewards: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAddRewardsInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          updateFarmConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateFarmConfigInstruction(input)),
          initializeUser: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeUserInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          transferOwnership: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getTransferOwnershipInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          rewardUserOnce: (input) =>
            addSelfPlanAndSendFunctions(client, getRewardUserOnceInstruction(input)),
          refreshFarm: (input) =>
            addSelfPlanAndSendFunctions(client, getRefreshFarmInstruction(input)),
          stake: (input) => addSelfPlanAndSendFunctions(client, getStakeInstruction(input)),
          setStakeDelegated: (input) =>
            addSelfPlanAndSendFunctions(client, getSetStakeDelegatedInstruction(input)),
          harvestReward: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getHarvestRewardInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          unstake: (input) => addSelfPlanAndSendFunctions(client, getUnstakeInstruction(input)),
          refreshUserState: (input) =>
            addSelfPlanAndSendFunctions(client, getRefreshUserStateInstruction(input)),
          withdrawUnstakedDeposits: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawUnstakedDepositsInstruction(input)),
          withdrawTreasury: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawTreasuryInstruction(input)),
          depositToFarmVault: (input) =>
            addSelfPlanAndSendFunctions(client, getDepositToFarmVaultInstruction(input)),
          withdrawFromFarmVault: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawFromFarmVaultInstruction(input)),
          withdrawSlashedAmount: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawSlashedAmountInstruction(input)),
          updateFarmAdmin: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateFarmAdminInstruction(input)),
          updateGlobalConfigAdmin: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateGlobalConfigAdminInstruction(input)),
          withdrawReward: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawRewardInstruction(input)),
          updateSecondDelegatedAuthority: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateSecondDelegatedAuthorityInstruction(input)
            ),
          closeEmptyUserState: (input) =>
            addSelfPlanAndSendFunctions(client, getCloseEmptyUserStateInstruction(input)),
          idlMissingTypes: (input) =>
            addSelfPlanAndSendFunctions(client, getIdlMissingTypesInstruction(input)),
        },
        identifyAccount: identifyFarmsAccount,
        identifyInstruction: identifyFarmsInstruction,
        parseInstruction: parseFarmsInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
